import { ITEM_IDS, type Condition } from './protocol';
// Add these 30 files later, then run pnpm check:audio. No speech is generated by this app.
export const audioPath = (condition: Condition, id: string) =>
  `/audio/${condition}/${id}.mp3`;
export const REQUIRED_AUDIO = (['fluent', 'disfluent'] as const).flatMap(
  (condition) =>
    ITEM_IDS.map((id) => ({ condition, id, path: audioPath(condition, id) })),
);
